using System.ClientModel;
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------

var researchNotes = new ResearchNotes();

var searchTool = AIFunctionFactory.Create(
    (string query) => WebSearchTool.SearchAsync(query),
    "web_search",
    "Searches the web for the given query and returns a list of result snippets.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise research note to save")] string note) =>
    {
        researchNotes.Add(note);
        return $"Note saved. You now have {researchNotes.Count} note(s).";
    },
    "add_note",
    "Saves a research note for later use in the final summary.");

var readNotesTool = AIFunctionFactory.Create(
    () => researchNotes.Count == 0
        ? "No notes yet."
        : string.Join("\n", researchNotes.All.Select((n, i) => $"{i + 1}. {n}")),
    "read_notes",
    "Returns all research notes collected so far.");

// ---------------------------------------------------------------------------
// Build the chat client with automatic tool invocation
// ---------------------------------------------------------------------------

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(new ApiKeyCredential(apiKey))
            .GetChatClient(modelName).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool],
    Temperature = 0.2f
};

// ---------------------------------------------------------------------------
// Agent system prompt
// ---------------------------------------------------------------------------

const string systemPrompt = """
    You are a research agent. Your goal is to thoroughly research a topic the user
    provides and produce a well-structured summary.

    Follow this workflow:
    1. Break the topic into 2-3 sub-questions.
    2. Use the web_search tool to find information for each sub-question.
    3. Use add_note to record the key facts and source URLs you discover.
    4. After gathering enough information, use read_notes to review everything.
    5. Produce a final, well-organized summary with sections and source references.

    Be thorough but concise. Always cite sources when possible.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching… (the agent may call tools several times)\n");
    Console.ResetColor();

    researchNotes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Please research the following topic: {topic}")
    };

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

