/// <summary>Simple in-memory note store.</summary>
sealed class ResearchNotes
{
    private readonly List<string> _notes = [];
    public int Count => _notes.Count;
    public IReadOnlyList<string> All => _notes;
    public void Add(string note) => _notes.Add(note);
    public void Clear() => _notes.Clear();
}

/// <summary>Lightweight web search using DuckDuckGo Lite (HTML scrape).</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            // Use DuckDuckGo's HTML-only endpoint to get search result snippets.
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var html = await Http.SendAsync(request)
                .ContinueWith(t => t.Result.Content.ReadAsStringAsync()).Unwrap();

            var results = ParseResults(html);

            return results.Count == 0
                ? "No results found."
                : JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    /// <summary>
    /// Extracts result titles, snippets, and URLs from DuckDuckGo Lite HTML.
    /// </summary>
    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();

        // DuckDuckGo Lite wraps each result snippet in <a class="result-link"> and
        // <td class="result-snippet">. We do a simple text parse to avoid adding an
        // HTML-parsing dependency.
        var snippetTag = "class=\"result-snippet\"";
        var linkTag = "class=\"result__a\"";
        var pos = 0;

        while (results.Count < 5)
        {
            // Find the next result link
            var linkIdx = html.IndexOf(linkTag, pos, StringComparison.Ordinal);
            if (linkIdx < 0) break;

            // Extract href
            var hrefStart = html.LastIndexOf("href=\"", linkIdx, Math.Min(linkIdx, 200),
                StringComparison.Ordinal);
            var urlValue = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                    urlValue = html[hrefStart..hrefEnd];
            }

            // Extract link text (title)
            var titleStart = html.IndexOf('>', linkIdx) + 1;
            var titleEnd = html.IndexOf('<', titleStart);
            var title = titleStart > 0 && titleEnd > titleStart
                ? StripTags(html[titleStart..titleEnd]).Trim()
                : "";

            // Find snippet
            var snippetIdx = html.IndexOf(snippetTag, linkIdx, StringComparison.Ordinal);
            var snippet = "";
            if (snippetIdx >= 0)
            {
                var snipStart = html.IndexOf('>', snippetIdx) + 1;
                var snipEnd = html.IndexOf("</td>", snipStart, StringComparison.Ordinal);
                if (snipStart > 0 && snipEnd > snipStart)
                    snippet = StripTags(html[snipStart..snipEnd]).Trim();
            }

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(title, snippet, urlValue));

            pos = linkIdx + linkTag.Length;
        }

        return results;
    }

    private static string StripTags(string html)
    {
        var output = new System.Text.StringBuilder(html.Length);
        var inTag = false;
        foreach (var ch in html)
        {
            if (ch == '<') { inTag = true; continue; }
            if (ch == '>') { inTag = false; continue; }
            if (!inTag) output.Append(ch);
        }
        return System.Net.WebUtility.HtmlDecode(output.ToString());
    }

    record SearchResult(string Title, string Snippet, string Url);
}

